async function recalcProgramme(db:D1Database,programmeId:string){const counts=await db.prepare("SELECT COUNT(*) total,SUM(CASE WHEN status='completed' THEN 1 ELSE 0 END) completed,SUM(CASE WHEN status='no_show' THEN 1 ELSE 0 END) no_show,SUM(CASE WHEN status='cancelled' THEN 1 ELSE 0 END) cancelled,SUM(CASE WHEN status IN ('accepted','on_the_way','arrived','in_session','reschedule_requested') THEN 1 ELSE 0 END) active FROM training_sessions WHERE programme_id=?").bind(programmeId).first<Row>();const total=Number(counts?.total||0),completed=Number(counts?.completed||0),noShow=Number(counts?.no_show||0),cancelled=Number(counts?.cancelled||0),active=Number(counts?.active||0),terminal=completed+cancelled+noShow===total;const status=terminal?(noShow===0&&cancelled===0?"completed":"completed_with_exceptions"):active>0||completed>0||noShow>0?"in_progress":"scheduled";await db.prepare("UPDATE training_programmes SET completed_sessions=?,no_show_sessions=?,cancelled_sessions=?,status=?,updated_at=? WHERE id=?").bind(completed,noShow,cancelled,status,Date.now(),programmeId).run();return{total,completed,noShow,cancelled,status,terminal};}
